// SPDX-License-Identifier: BSD-3-Clause
//
// Host test for the parts of this plugin that can be checked without a GPU.
//
// It compiles the real src/Kernel.cu (via kernels.inc, generated by
// run-tests.sh) with the shim in test/shim, emulates the thread mapping, and
// compares three things against a plain reference implementation:
//
//   1. IsVec4Addressable() decisions, including misaligned bases and negative
//      pitches - the cases where choosing the vector kernel would fault.
//   2. GainKernelRGBA32FVec4 vs GainKernelRGBA32FScalar, byte for byte, over
//      widths 0-63 (all four width % 4 classes), odd sizes and odd origins.
//   3. GainKernelRGBA16FHalf4 against a reference that rounds the same way, over
//      the frame shapes an earlier hardware run measured (1920x1080, 1919x1081
//      with and without a 64-byte pad, 63x1, 1x1) and over the widths where the
//      boundary check matters.
//   4. The hoisted row-pointer CPU loop vs the original per-pixel form.
//   5. Both 32F kernels run concurrently from several threads on disjoint buffers,
//      which is what "the kernel is reentrant" means: it reads only its
//      arguments and its own (thread-local) indices. This test is also the one
//      that gives ThreadSanitizer something real to look at.
//
// Exit status is 0 only if every case matches.
//
// Deliberately not tested here: anything that needs a device (stream ordering,
// multi-GPU selection, real launch configuration) or a host (action dispatch,
// clip preferences, the OpenGL/Metal/OpenCL paths).

#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <thread>
#include <vector>

#include "kernels.inc" // GainKernelRGBA32FVec4 / GainKernelRGBA32FScalar, verbatim

// The shim's stand-ins for the CUDA built-ins are thread_local: a kernel gets
// its indices from the launch, never from global state, so several host threads
// can emulate launches at the same time without touching each other.
thread_local dim3 blockIdx;
thread_local dim3 blockDim;
thread_local dim3 threadIdx;

namespace {

int g_failures = 0;

void fail(const char* what, int w, int h, int pad, int shift, int ox, int oy, int where)
{
    if (g_failures < 10) {
        std::printf("  FAIL %-8s w=%d h=%d pad=%d shift=%d origin=(%d,%d) at=%d\n",
                    what, w, h, pad, shift, ox, oy, where);
    }
    ++g_failures;
}

unsigned int g_seed = 12345u;

/// Deterministic values in roughly [-2, 2), including negatives.
float nextFloat()
{
    g_seed = g_seed * 1664525u + 1013904223u;
    unsigned int bits = (g_seed >> 9) | 0x3f000000u;
    float f;
    std::memcpy(&f, &bits, 4);
    return (f - 1.0f) * 4.0f;
}

/// OFX hands a plug-in `void*` plus a row stride (`kOfxImagePropRowBytes`), so
/// image planes are byte-addressed and only then read as float. That is exactly
/// what the plug-in does, and it is what this harness has to reproduce: the
/// alternative - assuming a packed float buffer - would test a different
/// program. Every fixture below is 16-byte aligned or deliberately offset by 4,
/// and the offset cases never take the vector path.
///
// cppcheck-suppress invalidPointerCast
inline float* asFloat(unsigned char* p) { return reinterpret_cast<float*>(p); }

// cppcheck-suppress invalidPointerCast
inline const float* asFloat(const unsigned char* p) { return reinterpret_cast<const float*>(p); }

// cppcheck-suppress invalidPointerCast
inline __half* asHalf(unsigned char* p) { return reinterpret_cast<__half*>(p); }

// cppcheck-suppress invalidPointerCast
inline const __half* asHalf(const unsigned char* p) { return reinterpret_cast<const __half*>(p); }

void referenceScale(const unsigned char* src, unsigned char* dst, int w, int h,
                    long long sp, long long dp, const float g[4])
{
    for (int y = 0; y < h; ++y) {
        const float* s = asFloat(src + y * sp);
        float* d = asFloat(dst + y * dp);
        for (int x = 0; x < w; ++x) {
            for (int c = 0; c < 4; ++c) {
                d[4LL * x + c] = s[4LL * x + c] * g[c];
            }
        }
    }
}

/// Runs the kernel over a grid the way the CUDA runtime would, with one thread
/// per pixel position. Returns the number of launches performed.
template <typename F>
long emulate(int w, int h, F launch)
{
    if (w <= 0 || h <= 0) {
        return 0; // an empty grid launches nothing
    }
    const dim3 block(16, 16, 1);
    const unsigned gx = static_cast<unsigned>((w + 15) / 16);
    const unsigned gy = static_cast<unsigned>((h + 15) / 16);
    blockDim = block;
    for (unsigned by = 0; by < gy; ++by) {
        for (unsigned bx = 0; bx < gx; ++bx) {
            for (unsigned ty = 0; ty < block.y; ++ty) {
                for (unsigned tx = 0; tx < block.x; ++tx) {
                    blockIdx = dim3(bx, by, 1);
                    threadIdx = dim3(tx, ty, 1);
                    launch();
                }
            }
        }
    }
    return 1;
}

// ---------------------------------------------------------------- 1. predicate

struct PredicateCase {
    const char* label;
    int srcShift;
    int dstShift;
    long long srcPitch;
    long long dstPitch;
    bool expected;
};

void testPredicate()
{
    std::printf("[1/5] IsVec4Addressable and IsHalf2Addressable decisions\n");

    alignas(16) static unsigned char a[4096];
    alignas(16) static unsigned char b[4096];

    const PredicateCase cases[] = {
        { "aligned base, aligned pitch",    0, 0,  256,  256, true  },
        { "src base + 4",                   4, 0,  256,  256, false },
        { "dst base + 8",                   0, 8,  256,  256, false },
        { "src pitch 256 + 8",              0, 0,  264,  256, false },
        { "negative pitch, multiple of 16", 0, 0, -256, -256, true  },
        { "negative pitch, not multiple",   0, 0, -264,  256, false },
        { "pitch 0 (single row)",           0, 0,    0,    0, true  },
    };

    for (const PredicateCase& c : cases) {
        const bool got = mcofx::IsVec4Addressable(a + c.srcShift, b + c.dstShift,
                                                  c.srcPitch, c.dstPitch);
        std::printf("  %-34s %-4s (expected %s)\n", c.label, got ? "yes" : "no",
                    c.expected ? "yes" : "no");
        if (got != c.expected) {
            fail("predicate", 0, 0, 0, c.srcShift, 0, 0, 0);
        }
    }

    // The 16F path needs a quarter of the alignment: four-byte rows, not sixteen.
    // These cases are what makes the difference visible rather than asserted.
    struct HalfPredicateCase {
        const char* label;
        int srcShift;
        int dstShift;
        long long srcPitch;
        long long dstPitch;
        bool expected;
    };
    const HalfPredicateCase halfCases[] = {
        { "half2: aligned, pitch 15360",      0, 0, 15360, 15360, true  },
        { "half2: base + 2 (would fault)",    2, 0, 15360, 15360, false },
        { "half2: base + 4",                  4, 0, 15360, 15360, true  },
        { "half2: pitch + 2",                 0, 0, 15362, 15360, false },
        { "half2: negative pitch /4",         0, 0, -15360, -15360, true },
        { "half2: negative pitch not /4",     0, 0, -15362, 15360, false },
        { "half2: pitch 0 (single row)",      0, 0,     0,     0, true },
    };
    for (const HalfPredicateCase& c : halfCases) {
        const bool got = mcofx::IsHalf2Addressable(a + c.srcShift, b + c.dstShift,
                                                   c.srcPitch, c.dstPitch);
        std::printf("  %-34s %-4s (expected %s)\n", c.label, got ? "yes" : "no",
                    c.expected ? "yes" : "no");
        if (got != c.expected) {
            fail("half-pred", 0, 0, 0, c.srcShift, 0, 0, 0);
        }
    }
}

// ------------------------------------------------- 2. kernels, byte for byte

void testKernels()
{
    std::printf("[2/5] vec4 kernel vs scalar kernel vs reference\n");

    const float g[4] = { 1.75f, 0.5f, 2.25f, 1.0f };
    const float4 gain4 = make_float4(g[0], g[1], g[2], g[3]);

    // Widths chosen so every residue mod 4 appears several times, including 0.
    const int widths[]  = { 0, 1, 2, 3, 4, 5, 6, 7, 8, 15, 16, 17, 31, 32, 33, 63 };
    const int heights[] = { 1, 2, 3, 5 };
    const int pads[]    = { 0, 16, 8 };  // 8 => pitch not 16-byte aligned
    const int shifts[]  = { 0, 4 };      // 4 => base pointer not 16-byte aligned
    const int oxs[]     = { 0, 5, 17 };
    const int oys[]     = { 0, 3, 9 };

    long launches = 0, vecRuns = 0, scalarRuns = 0;

    for (int w : widths) {
        for (int h : heights) {
            for (int pad : pads) {
                for (int shift : shifts) {
                    for (int ox : oxs) {
                        for (int oy : oys) {
                            const int boundsW = ox + w + 2;
                            const int boundsH = oy + h + 2;
                            const int sp = boundsW * 16 + pad;
                            const int dp = boundsW * 16 + pad;

                            unsigned char* srcAlloc = nullptr;
                            unsigned char* dstAlloc = nullptr;
                            if (posix_memalign(reinterpret_cast<void**>(&srcAlloc), 16,
                                               static_cast<size_t>(sp) * boundsH + 64) != 0) {
                                std::printf("  allocation failed\n");
                                ++g_failures;
                                return;
                            }
                            if (posix_memalign(reinterpret_cast<void**>(&dstAlloc), 16,
                                               static_cast<size_t>(dp) * boundsH + 64) != 0) {
                                std::printf("  allocation failed\n");
                                ++g_failures;
                                std::free(srcAlloc);
                                return;
                            }

                            unsigned char* srcBase = srcAlloc + shift;
                            unsigned char* dstBase = dstAlloc + shift;

                            for (int y = 0; y < boundsH; ++y) {
                                for (int x = 0; x < boundsW; ++x) {
                                    float* p = asFloat(srcBase +
                                                       static_cast<long long>(y) * sp +
                                                       static_cast<long long>(x) * 16);
                                    for (int c = 0; c < 4; ++c) {
                                        p[c] = nextFloat();
                                    }
                                }
                            }

                            const unsigned char* srcOrigin = srcBase +
                                                             static_cast<long long>(oy) * sp +
                                                             static_cast<long long>(ox) * 16;
                            unsigned char* dstOrigin = dstBase +
                                                       static_cast<long long>(oy) * dp +
                                                       static_cast<long long>(ox) * 16;

                            std::memset(dstBase, 0x7f, static_cast<size_t>(dp) * boundsH);
                            referenceScale(srcOrigin, dstOrigin, w, h, sp, dp, g);

                            const size_t rowBytes = static_cast<size_t>(w) * 16;
                            unsigned char* expected = static_cast<unsigned char*>(
                                std::malloc(rowBytes * static_cast<size_t>(h > 0 ? h : 1) + 1));
                            for (int y = 0; y < h; ++y) {
                                std::memcpy(expected + rowBytes * static_cast<size_t>(y),
                                            dstOrigin + static_cast<long long>(y) * dp, rowBytes);
                            }

                            const bool vecLegal =
                                mcofx::IsVec4Addressable(srcOrigin, dstOrigin, sp, dp);

                            for (int pass = 0; pass < 2; ++pass) {
                                if ((pass == 0) != vecLegal) {
                                    continue; // only run the kernel the launcher would pick
                                }
                                std::memset(dstBase, 0x5a, static_cast<size_t>(dp) * boundsH);
                                if (pass == 0) {
                                    launches += emulate(w, h, [&] {
                                        GainKernelRGBA32FVec4(
                                            asFloat(srcOrigin),
                                            asFloat(dstOrigin), w, h, sp, dp, gain4);
                                    });
                                    ++vecRuns;
                                } else {
                                    launches += emulate(w, h, [&] {
                                        GainKernelRGBA32FScalar(
                                            asFloat(srcOrigin),
                                            asFloat(dstOrigin), w, h, sp, dp, gain4);
                                    });
                                    ++scalarRuns;
                                }

                                for (int y = 0; y < h; ++y) {
                                    if (std::memcmp(expected + rowBytes * static_cast<size_t>(y),
                                                    dstOrigin + static_cast<long long>(y) * dp,
                                                    rowBytes) != 0) {
                                        fail(pass == 0 ? "vec4" : "scalar", w, h, pad, shift, ox, oy,
                                             y + 1);
                                        break;
                                    }
                                }

                                // Nothing outside the render window may be written.
                                for (int y = 0; y < boundsH; ++y) {
                                    for (int x = 0; x < boundsW; ++x) {
                                        const bool inside =
                                            (x >= ox && x < ox + w && y >= oy && y < oy + h);
                                        if (inside) {
                                            continue;
                                        }
                                        const unsigned char* p = dstBase +
                                            static_cast<long long>(y) * dp +
                                            static_cast<long long>(x) * 16;
                                        for (int byte = 0; byte < 16; ++byte) {
                                            if (p[byte] != 0x5a) {
                                                fail("overrun", w, h, pad, shift, ox, oy, y);
                                                y = boundsH;
                                                break;
                                            }
                                        }
                                    }
                                }
                            }

                            std::free(expected);
                            std::free(srcAlloc);
                            std::free(dstAlloc);
                        }
                    }
                }
            }
        }
    }

    std::printf("  %ld grid launches (vec4=%ld scalar=%ld), failures=%d\n",
                launches, vecRuns, scalarRuns, g_failures);
}

// -------------------------------------- 3. 16F kernel, over measured shapes

/// One shape the half kernel is driven over: a frame, plus padding added to the
/// pitch so the row stride is not simply width * 8.
struct HalfShape {
    int w;
    int h;
    int pad;
    const char* label;
    bool tabulate; // print one line per shape in the summary table
};

/// Runs one shape and returns its mismatch count. `gain` is in halves already,
/// because the kernel takes halves: the reference has to see the same operands.
int runHalfShape(const HalfShape& shape, const __half2 gainRG, const __half2 gainBA,
                 const __half g[4])
{
    const int boundsW = shape.w + 2;
    const int boundsH = shape.h + 2;
    const int pitch = boundsW * 8 + shape.pad;
    const size_t bytes = static_cast<size_t>(pitch) * static_cast<size_t>(boundsH);

    unsigned char* src = nullptr;
    unsigned char* dst = nullptr;
    if (posix_memalign(reinterpret_cast<void**>(&src), 8, bytes) != 0) {
        return 1;
    }
    if (posix_memalign(reinterpret_cast<void**>(&dst), 8, bytes) != 0) {
        std::free(src);
        return 1;
    }

    for (int y = 0; y < boundsH; ++y) {
        __half* row = asHalf(src + static_cast<long long>(y) * pitch);
        for (int i = 0; i < boundsW * 4; ++i) {
            row[i] = __float2half_rn(nextFloat());
        }
    }
    std::memset(dst, 0x7f, bytes);

    const int ox = 1;
    const int oy = 1;
    const unsigned char* srcOrigin = src + static_cast<long long>(oy) * pitch +
                                     static_cast<long long>(ox) * 8;
    unsigned char* dstOrigin = dst + static_cast<long long>(oy) * pitch +
                               static_cast<long long>(ox) * 8;

    if (!mcofx::IsHalf2Addressable(srcOrigin, dstOrigin, pitch, pitch)) {
        std::printf("  FAIL %s: fixture is not half2-addressable\n", shape.label);
        std::free(src);
        std::free(dst);
        return 1;
    }

    emulate(shape.w, shape.h, [&] {
        GainKernelRGBA16FHalf4(asHalf(srcOrigin), asHalf(dstOrigin), shape.w, shape.h, pitch,
                               pitch, gainRG, gainBA);
    });

    // Reference: the same conversion and the same single rounding, per half.
    int wrong = 0;
    for (int y = 0; y < shape.h; ++y) {
        const __half* s = asHalf(srcOrigin + static_cast<long long>(y) * pitch);
        const __half* d = asHalf(dstOrigin + static_cast<long long>(y) * pitch);
        for (int x = 0; x < shape.w * 4; ++x) {
            const float product = __half2float(s[x]) * __half2float(g[x % 4]);
            const __half expected = __float2half_rn(product);
            if (d[x].bits != expected.bits) {
                ++wrong;
                if (wrong == 1) {
                    std::printf("  FAIL %s at x=%d y=%d: %04x != %04x\n", shape.label, x, y,
                                static_cast<unsigned>(d[x].bits),
                                static_cast<unsigned>(expected.bits));
                }
            }
        }
    }

    // Nothing outside the render window may be written: the 16F kernel writes
    // 8 bytes per pixel, so a wrong index would show up here first.
    if (wrong == 0) {
        for (int y = 0; y < boundsH && wrong == 0; ++y) {
            const unsigned char* row = dst + static_cast<long long>(y) * pitch;
            for (int x = 0; x < boundsW * 8; ++x) {
                const int px = x / 8;
                const int py = y;
                const bool inside =
                    (px >= ox && px < ox + shape.w && py >= oy && py < oy + shape.h);
                if (!inside && row[x] != 0x7f) {
                    std::printf("  FAIL %s: wrote outside the window at (%d,%d)\n", shape.label,
                                px, py);
                    wrong = 1;
                    break;
                }
            }
        }
    }

    if (shape.tabulate) {
        std::printf("  %-24s pitch %5d  %7d pixels  %s\n", shape.label, pitch,
                    shape.w * shape.h, wrong == 0 ? "ok" : "MISMATCH");
    }

    std::free(src);
    std::free(dst);
    return wrong;
}

void testHalfKernel()
{
    std::printf("[3/5] 16F half kernel, over the frame shapes an earlier run measured\n");

    const float gainF[4] = { 1.75f, 0.5f, 2.25f, 1.0f };
    const __half g[4] = { __float2half_rn(gainF[0]), __float2half_rn(gainF[1]),
                          __float2half_rn(gainF[2]), __float2half_rn(gainF[3]) };
    const __half2 gainRG = __halves2half2(g[0], g[1]);
    const __half2 gainBA = __halves2half2(g[2], g[3]);

    // The shapes from evidence/2026-11-26-windows/kernel-shapes.log, at the
    // pitch a 16F frame has (8 bytes per pixel): the odd width and the padded
    // row are the two that a float4 kernel could not take.
    const HalfShape measured[] = {
        { 1920, 1080, 0, "1920x1080", true },
        { 1919, 1081, 0, "1919x1081 odd width", true },
        { 1919, 1081, 64, "1919x1081, 64-byte pad", true },
        { 63, 1, 0, "63x1", true },
        { 1, 1, 0, "1x1", true },
    };

    long shapes = 0;
    long wrong = 0;
    for (const HalfShape& shape : measured) {
        wrong += runHalfShape(shape, gainRG, gainBA, g);
        ++shapes;
    }

    // Widths around the block boundary, odd heights and a padded pitch: the
    // cases where the boundary check or the row arithmetic can be off by one.
    const int widths[] = { 1, 2, 3, 4, 5, 7, 8, 9, 15, 16, 17, 31, 33 };
    const int heights[] = { 1, 2, 3, 5 };
    const int pads[] = { 0, 4, 8 };
    for (int w : widths) {
        for (int h : heights) {
            for (int pad : pads) {
                wrong += runHalfShape(HalfShape{ w, h, pad, "boundary", false }, gainRG, gainBA, g);
                ++shapes;
            }
        }
    }

    // A negative pitch, the flipped-image case the predicate allows.
    {
        HalfShape flipped{ 17, 5, 0, "17x5 negative pitch", true };
        const int boundsW = flipped.w + 2;
        const int boundsH = flipped.h + 2;
        const int pitch = boundsW * 8;
        const size_t bytes = static_cast<size_t>(pitch) * static_cast<size_t>(boundsH);
        unsigned char* src = static_cast<unsigned char*>(std::malloc(bytes));
        unsigned char* dst = static_cast<unsigned char*>(std::malloc(bytes));
        for (int y = 0; y < boundsH; ++y) {
            __half* row = asHalf(src + static_cast<long long>(y) * pitch);
            for (int i = 0; i < boundsW * 4; ++i) {
                row[i] = __float2half_rn(nextFloat());
            }
        }
        std::memset(dst, 0x7f, bytes);
        // Row 0 of the window is the last row of the buffer being addressed.
        unsigned char* srcOrigin = src + static_cast<long long>(boundsH - 2) * pitch + 8;
        unsigned char* dstOrigin = dst + static_cast<long long>(boundsH - 2) * pitch + 8;
        emulate(flipped.w, flipped.h, [&] {
            GainKernelRGBA16FHalf4(asHalf(srcOrigin), asHalf(dstOrigin), flipped.w, flipped.h,
                                   -pitch, -pitch, gainRG, gainBA);
        });
        int bad = 0;
        for (int y = 0; y < flipped.h; ++y) {
            const __half* s = asHalf(srcOrigin - static_cast<long long>(y) * pitch);
            const __half* d = asHalf(dstOrigin - static_cast<long long>(y) * pitch);
            for (int x = 0; x < flipped.w * 4; ++x) {
                const __half expected = __float2half_rn(__half2float(s[x]) * __half2float(g[x % 4]));
                if (d[x].bits != expected.bits) ++bad;
            }
        }
        if (bad != 0) {
            std::printf("  FAIL negative pitch: %d halves wrong\n", bad);
        }
        std::printf("  %-24s pitch %5d  %7d pixels  %s\n", flipped.label, -pitch,
                    flipped.w * flipped.h, bad == 0 ? "ok" : "MISMATCH");
        wrong += bad;
        ++shapes;
        std::free(src);
        std::free(dst);
    }

    std::printf("  %ld shapes, %ld halves wrong\n", shapes, wrong);
    if (wrong != 0) {
        ++g_failures;
    }
}

// ------------------------------------------- 3. CPU loop hoist, byte for byte

void testCpuLoop()
{
    std::printf("[4/5] hoisted row pointers vs per-pixel addressing (CPU path)\n");

    const float gain[4] = { 1.5f, 0.25f, 3.0f, 1.0f };
    const int widths[] = { 1, 2, 3, 5, 17, 33 };
    long components = 0;
    const int before = g_failures;

    for (int w : widths) {
        const int h = 6;
        const int boundsW = w + 6;
        const int boundsH = h + 4;
        const int pitch = boundsW * 16;
        const int ox = 3;
        const int oy = 2;

        unsigned char* src = static_cast<unsigned char*>(
            std::calloc(static_cast<size_t>(pitch) * boundsH, 1));
        unsigned char* oldWay = static_cast<unsigned char*>(
            std::calloc(static_cast<size_t>(pitch) * boundsH, 1));
        unsigned char* newWay = static_cast<unsigned char*>(
            std::calloc(static_cast<size_t>(pitch) * boundsH, 1));
        for (size_t i = 0; i < static_cast<size_t>(pitch) * boundsH; ++i) {
            src[i] = static_cast<unsigned char>(i * 31 + 7);
        }

        // Previous shape: one address computation per pixel.
        for (int y = oy; y < oy + h; ++y) {
            float* dst = asFloat(oldWay + static_cast<long long>(y) * pitch +
                                 static_cast<long long>(ox) * 16);
            for (int x = ox; x < ox + w; ++x) {
                const float* s = asFloat(src + static_cast<long long>(y) * pitch +
                                         static_cast<long long>(x) * 16);
                for (int c = 0; c < 4; ++c) {
                    dst[c] = s[c] * gain[c];
                }
                dst += 4;
            }
        }

        // Shipped shape: row pointers hoisted, pointers advanced in the loop.
        for (int y = oy; y < oy + h; ++y) {
            float* dstRow = asFloat(newWay + static_cast<long long>(y) * pitch +
                                    static_cast<long long>(ox) * 16);
            const float* srcRow = asFloat(src + static_cast<long long>(y) * pitch +
                                          static_cast<long long>(ox) * 16);
            for (int x = ox; x < ox + w; ++x, dstRow += 4, srcRow += 4) {
                for (int c = 0; c < 4; ++c) {
                    dstRow[c] = srcRow[c] * gain[c];
                }
            }
        }

        components += static_cast<long>(w) * h * 4;
        if (std::memcmp(oldWay, newWay, static_cast<size_t>(pitch) * boundsH) != 0) {
            fail("cpu-loop", w, h, 0, 0, ox, oy, 0);
        }
        std::free(src);
        std::free(oldWay);
        std::free(newWay);
    }

    std::printf("  %ld components compared, failures=%d\n", components, g_failures - before);
}

// --------------------------------------- 4. concurrent runs (reentrancy, TSan)

struct ConcCase {
    int w;
    int h;
    int pad;
    int shift;
};

/// Runs one fixture on buffers owned by this call and returns its failure count.
/// No shared state is touched: that is the property under test.
int runConcurrentCase(const ConcCase& c, const float4& gain4, const float g[4], bool& usedVec4)
{
    const int boundsW = c.w + 2;
    const int boundsH = c.h + 2;
    const int pitch = boundsW * 16 + c.pad;
    const size_t bytes = static_cast<size_t>(pitch) * boundsH + 64;

    unsigned char* srcAlloc = nullptr;
    unsigned char* dstAlloc = nullptr;
    if (posix_memalign(reinterpret_cast<void**>(&srcAlloc), 16, bytes) != 0) {
        return 1;
    }
    if (posix_memalign(reinterpret_cast<void**>(&dstAlloc), 16, bytes) != 0) {
        std::free(srcAlloc);
        return 1;
    }

    unsigned char* srcBase = srcAlloc + c.shift;
    unsigned char* dstBase = dstAlloc + c.shift;

    // Local generator: the shared one would be a data race, and a race is not
    // what this test is meant to find.
    unsigned int seed = 999u + static_cast<unsigned int>(c.w * 31 + c.h * 7);
    for (int y = 0; y < boundsH; ++y) {
        for (int x = 0; x < boundsW; ++x) {
            float* p = asFloat(srcBase + static_cast<long long>(y) * pitch +
                               static_cast<long long>(x) * 16);
            for (int k = 0; k < 4; ++k) {
                seed = seed * 1664525u + 1013904223u;
                const unsigned int bits = (seed >> 9) | 0x3f000000u;
                float f;
                std::memcpy(&f, &bits, 4);
                p[k] = (f - 1.0f) * 4.0f;
            }
        }
    }

    const unsigned char* srcOrigin = srcBase + static_cast<long long>(pitch) +
                                     static_cast<long long>(16);
    unsigned char* dstOrigin = dstBase + static_cast<long long>(pitch) +
                               static_cast<long long>(16);

    std::vector<unsigned char> ref(static_cast<size_t>(c.w) * static_cast<size_t>(c.h) * 16);
    referenceScale(srcOrigin, ref.data(), c.w, c.h, pitch,
                   static_cast<long long>(c.w) * 16, g);

    int failures = 0;
    usedVec4 = mcofx::IsVec4Addressable(srcOrigin, dstOrigin, pitch, pitch);
    if (usedVec4) {
        emulate(c.w, c.h, [&] {
            GainKernelRGBA32FVec4(asFloat(srcOrigin), asFloat(dstOrigin), c.w, c.h, pitch, pitch,
                                  gain4);
        });
    } else {
        emulate(c.w, c.h, [&] {
            GainKernelRGBA32FScalar(asFloat(srcOrigin), asFloat(dstOrigin), c.w, c.h, pitch, pitch,
                                    gain4);
        });
    }

    for (int y = 0; y < c.h; ++y) {
        if (std::memcmp(ref.data() + static_cast<size_t>(y) * static_cast<size_t>(c.w) * 16,
                        dstOrigin + static_cast<long long>(y) * pitch,
                        static_cast<size_t>(c.w) * 16) != 0) {
            ++failures;
            break;
        }
    }

    std::free(srcAlloc);
    std::free(dstAlloc);
    return failures;
}

void testConcurrent()
{
    std::printf("[5/5] concurrent kernel runs on disjoint buffers (reentrancy)\n");

    const ConcCase cases[] = {
        { 17, 5, 0, 0 },  // vec4
        { 32, 3, 16, 0 }, // vec4
        { 9, 7, 8, 4 },   // scalar: base 4 bytes off
        { 64, 2, 0, 0 },  // vec4
        { 5, 9, 8, 4 },   // scalar
        { 40, 4, 16, 0 }, // vec4
    };
    const int kThreads = static_cast<int>(sizeof(cases) / sizeof(cases[0]));
    const float g[4] = { 1.25f, 0.5f, 2.0f, 1.0f };
    const float4 gain4 = make_float4(g[0], g[1], g[2], g[3]);

    std::vector<int> failures(static_cast<size_t>(kThreads), 0);
    std::vector<char> vecUsed(static_cast<size_t>(kThreads), 0);

    std::vector<std::thread> threads;
    threads.reserve(static_cast<size_t>(kThreads));
    for (int i = 0; i < kThreads; ++i) {
        threads.emplace_back([&, i] {
            bool vec = false;
            failures[static_cast<size_t>(i)] =
                runConcurrentCase(cases[i], gain4, g, vec);
            vecUsed[static_cast<size_t>(i)] = vec ? 1 : 0;
        });
    }
    for (std::thread& t : threads) {
        t.join();
    }

    long total = 0;
    long vec4 = 0;
    for (int i = 0; i < kThreads; ++i) {
        total += failures[static_cast<size_t>(i)];
        vec4 += vecUsed[static_cast<size_t>(i)] ? 1 : 0;
    }

    std::printf("  %d threads, %ld vec4 + %ld scalar, failures=%ld\n",
                kThreads, vec4, kThreads - vec4, total);
    if (total != 0) {
        ++g_failures;
    }
}

} // namespace

int main()
{
    testPredicate();
    testKernels();
    testHalfKernel();
    testCpuLoop();
    testConcurrent();

    if (g_failures == 0) {
        std::printf("\nPASS: all cases match\n");
        return 0;
    }
    std::printf("\nFAIL: %d mismatches\n", g_failures);
    return 1;
}
